/**
 * Construct an empty LSDB (RFC 2328 §12).
 */
lr_ospf_lsdb_t lr_ospf_lsdb_new(void);

/**
 * Drop a boxed LSDB. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been produced by `lr_ospf_lsdb_new` and not already freed.
 */
void lr_ospf_lsdb_free(lr_ospf_lsdb_t r);

/**
 * Install one LSA into the LSDB (RFC 2328 §13). The `lsa` handle is
 * *consumed* — the caller must not use it after this call.
 *
 * Returns:
 * - 0 = NoChange (byte-identical reinstall, no generation bump).
 * - 1 = NewEntry (a new LSA was added).
 * - 2 = Refreshed (an existing LSA was replaced with newer content).
 * - 3 = Duplicate (an older-instance duplicate was dropped).
 * - Negative on error.
 *
 * # Safety
 * `r` must be a valid LSDB handle. `lsa` must be a valid LSA handle.
 */
int32_t lr_ospf_lsdb_install(lr_ospf_lsdb_t r, lr_ospf_lsa_box_t lsa, uint64_t now_ms);

/**
 * Remove one LSA by (ls_type, link_state_id, advertising_router).
 * Returns 1 when an LSA was removed, 0 when the key was absent.
 *
 * # Safety
 * `r` must be a valid LSDB handle.
 */
int32_t lr_ospf_lsdb_remove(lr_ospf_lsdb_t r,
                            uint16_t ls_type,
                            uint32_t link_state_id,
                            uint32_t advertising_router);

/**
 * Read one LSA by key. Returns 0 on success and writes a NEW
 * `lr_ospf_lsa_box_t` handle (a *copy* the caller frees via
 * `lr_ospf_lsa_free`) to `*out`. Returns 0 with `*out = NULL` when
 * the key is absent.
 *
 * # Safety
 * `r` must be a valid LSDB handle. `out` must point to writable memory.
 */
int32_t lr_ospf_lsdb_get(lr_ospf_lsdb_t r,
                         uint16_t ls_type,
                         uint32_t link_state_id,
                         uint32_t advertising_router,
                         lr_ospf_lsa_box_t *out);

/**
 * Number of LSAs in the LSDB. Returns 0 on a NULL handle.
 *
 * # Safety
 * `r` must be a valid LSDB handle.
 */
uintptr_t lr_ospf_lsdb_len(lr_ospf_lsdb_t r);

/**
 * True when the LSDB holds no LSAs. Returns 1 on a NULL handle.
 *
 * # Safety
 * See [`lr_ospf_lsdb_len`].
 */
uint8_t lr_ospf_lsdb_is_empty(lr_ospf_lsdb_t r);

/**
 * Read every LSA header as a flat array (RFC 2328 §A.4.1). On success
 * writes a freshly-allocated `lr_ospf_lsa_hdr_t*` to `*out` and the
 * count to `*out_count`. The caller owns the array and must free it
 * via `lr_ospf_lsa_hdr_array_free`.
 *
 * # Safety
 * `r` must be a valid LSDB handle. `out` and `out_count` must point
 * to writable memory.
 */
int32_t lr_ospf_lsdb_headers(lr_ospf_lsdb_t r,
                             struct lr_ospf_lsa_hdr_t **out,
                             uintptr_t *out_count);

/**
 * Free an LSA header array returned by `lr_ospf_lsdb_headers`. Safe
 * to call with NULL.
 *
 * # Safety
 * `ptr` must have been produced by `lr_ospf_lsdb_headers` and `count`
 * must be the value written to `*out_count` by that call.
 */
void lr_ospf_lsa_hdr_array_free(struct lr_ospf_lsa_hdr_t *ptr, uintptr_t count);

/**
 * Construct an LSA from a header handle + body bytes. The header
 * handle is *consumed*. Returns NULL on a NULL header.
 *
 * # Safety
 * `header` must be a valid LSA header handle. `body` must point to
 * `body_len` readable bytes (NULL only when `body_len == 0`).
 */
lr_ospf_lsa_box_t lr_ospf_lsa_new(lr_ospf_lsa_hdr_box_t header,
                                  const uint8_t *body,
                                  uintptr_t body_len);

/**
 * Read the header fields of an LSA into `*out`. Returns 0 on success.
 *
 * # Safety
 * `lsa` must be a valid LSA handle. `out` must point to writable
 * memory of size `lr_ospf_lsa_hdr_t`.
 */
int32_t lr_ospf_lsa_header_get(lr_ospf_lsa_box_t lsa, struct lr_ospf_lsa_hdr_t *out);

/**
 * Read the body bytes of an LSA. Returns 0 on success and writes a
 * freshly-allocated `lr_bytes_t` to `*out` (the caller frees via
 * `lr_bytes_free`).
 *
 * # Safety
 * `lsa` must be a valid LSA handle. `out` must point to writable memory.
 */
int32_t lr_ospf_lsa_body(lr_ospf_lsa_box_t lsa, struct lr_bytes_t *out);

/**
 * Encode the LSA as the 20-byte header + body (RFC 2328 §A.4 wire
 * form). Returns 0 on success and writes a freshly-allocated
 * `lr_bytes_t` to `*out`.
 *
 * # Safety
 * `lsa` must be a valid LSA handle. `out` must point to writable memory.
 */
int32_t lr_ospf_lsa_to_wire(lr_ospf_lsa_box_t lsa, struct lr_bytes_t *out);

/**
 * Drop a boxed LSA. Safe to call with NULL.
 *
 * # Safety
 * `lsa` must have been produced by `lr_ospf_lsa_new` /
 * `lr_ospf_lsdb_get` and not already freed.
 */
void lr_ospf_lsa_free(lr_ospf_lsa_box_t lsa);

/**
 * Compute and store the LSA's Fletcher-16 checksum (RFC 2328 §C.4)
 * and the length field, in place. Subsequent `lr_ospf_lsa_to_wire`
 * calls produce a wire form that round-trips through
 * `lr_ospf_lsa_checksum_ok`. Returns 0 on success, `LR_ERR_NULL`
 * on a NULL handle.
 *
 * # Safety
 * `lsa` must be a valid LSA handle.
 */
int32_t lr_ospf_lsa_finalize(lr_ospf_lsa_box_t lsa);

/**
 * Verify the LSA's Fletcher-16 checksum (RFC 2328 §C.4). Returns 1
 * when the checksum is valid, 0 otherwise (including on a NULL
 * handle).
 *
 * This is the LSA-handle variant; the raw-bytes variant
 * `lr_ospf_lsa_checksum_ok` in `core_extras.rs` operates on a flat
 * byte buffer without going through an LSA handle.
 *
 * # Safety
 * `lsa` must be a valid LSA handle.
 */
uint8_t lr_ospf_lsa_handle_checksum_ok(lr_ospf_lsa_box_t lsa);

/**
 * Build a MaxAge-flush copy of the LSA (RFC 2328 §14: ls_age =
 * MaxAge, sequence number bumped). Writes a new LSA handle to
 * `*out` (caller frees with `lr_ospf_lsa_free`). Returns 1 when a
 * flush was produced, 0 when the LSA cannot be flushed (e.g. it is
 * already MaxAge) or the input handle is NULL.
 *
 * # Safety
 * `lsa` must be a valid LSA handle. `out` must point to a writable
 * `lr_ospf_lsa_box_t`.
 */
uint8_t lr_ospf_lsa_maxage_flush(lr_ospf_lsa_box_t lsa, lr_ospf_lsa_box_t *out);

/**
 * Compute the LSA's key (RFC 2328 §12.1 — `(ls_type, link_state_id,
 * advertising_router)`). Writes the three fields to the out-pointers.
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle.
 *
 * # Safety
 * `lsa` must be a valid LSA handle. `out_ls_type`, `out_link_state_id`
 * and `out_advertising_router` must point to writable `uint16_t` /
 * `uint32_t` / `uint32_t`.
 */
int32_t lr_ospf_lsa_key(lr_ospf_lsa_box_t lsa,
                        uint16_t *out_ls_type,
                        uint32_t *out_link_state_id,
                        uint32_t *out_advertising_router);

/**
 * Construct an LSA header from the 8 fields (RFC 2328 §A.4.1).
 */
lr_ospf_lsa_hdr_box_t lr_ospf_lsa_header_new(uint16_t ls_age,
                                             uint8_t options,
                                             uint16_t ls_type,
                                             uint32_t link_state_id,
                                             uint32_t advertising_router,
                                             uint32_t ls_sequence_number,
                                             uint16_t ls_checksum,
                                             uint16_t length);

/**
 * Drop a boxed LSA header. Safe to call with NULL.
 *
 * # Safety
 * `h` must have been produced by `lr_ospf_lsa_header_new` and not
 * already freed.
 */
void lr_ospf_lsa_header_free(lr_ospf_lsa_hdr_box_t h);

/**
 * Returns the LSAs whose `ls_sequence_number` is due for refresh
 * (RFC 2328 §14.1 — `LSRefreshTime`, 30 minutes by default). The
 * embedder re-originates each LSA (bumping the sequence, zeroing
 * the age) and re-installs it via [`lr_ospf_lsdb_install`].
 *
 * `advertising_router` is the router-id whose self-originated LSAs
 * to refresh (RFC 2328 §14.1 only refreshes LSAs originated by
 * this router). Pass 0 to match all LSAs (useful for tests).
 *
 * Writes a freshly-allocated `lr_ospf_lsa_box_t*` array to `*out`
 * and the count to `*out_count`. The caller owns the array and each
 * LSA handle inside it; free the array via
 * [`lr_ospf_lsa_array_free`] (which also frees each LSA handle).
 *
 * Returns 0 on success, `LR_ERR_NULL` (-1) on a null handle / null
 * out pointer, `LR_ERR_PANIC` (-4) on a panic.
 *
 * # Safety
 * `r` must be a valid LSDB handle. `out` and `out_count` must point
 * to writable memory.
 */
int32_t lr_ospf_lsdb_refresh_due(lr_ospf_lsdb_t r,
                                 uint32_t advertising_router,
                                 uint64_t now_ms,
                                 lr_ospf_lsa_box_t **out,
                                 uintptr_t *out_count);

/**
 * Ages out LSAs that have reached `MaxAge` (RFC 2328 §14 — MaxAge
 * is 3600 seconds). Returns the LSAs that were purged from the
 * LSDB; the embedder re-floods them as MaxAge LSAs to flush them
 * from neighbors' LSDBs.
 *
 * Writes a freshly-allocated `lr_ospf_lsa_box_t*` array to `*out`
 * and the count to `*out_count`. The caller owns the array and each
 * LSA handle inside it; free via [`lr_ospf_lsa_array_free`].
 *
 * # Safety
 * `r` must be a valid LSDB handle. `out` and `out_count` must point
 * to writable memory.
 */
int32_t lr_ospf_lsdb_age_out(lr_ospf_lsdb_t r,
                             uint64_t now_ms,
                             lr_ospf_lsa_box_t **out,
                             uintptr_t *out_count);

/**
 * Free an LSA handle array returned by [`lr_ospf_lsdb_refresh_due`]
 * or [`lr_ospf_lsdb_age_out`]. Also frees each LSA handle inside the
 * array. Safe to call with NULL / count=0.
 *
 * # Safety
 * `ptr` must have been produced by `lr_ospf_lsdb_refresh_due` or
 * `lr_ospf_lsdb_age_out`, and `count` must be the value written to
 * `*out_count` by that call. Double-free is undefined behaviour.
 */
void lr_ospf_lsa_array_free(lr_ospf_lsa_box_t *ptr, uintptr_t count);

/**
 * Construct an `OspfNeighbor` for the given router-id (RFC 2328
 * §10.1 — the neighbor starts in Down state).
 */
lr_ospf_neighbor_t lr_ospf_neighbor_new(uint32_t router_id);

/**
 * Drop a boxed OspfNeighbor. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been produced by `lr_ospf_neighbor_new` and not
 * already freed.
 */
void lr_ospf_neighbor_free(lr_ospf_neighbor_t r);

/**
 * Read the current FSM state. Returns 0 on a NULL handle.
 *
 * # Safety
 * `r` must be a valid OspfNeighbor handle.
 */
int32_t lr_ospf_neighbor_state(lr_ospf_neighbor_t r);

/**
 * Drive the FSM with `HelloSeen` (RFC 2328 §10.5 — a Hello listing
 * us as seen arrived from this neighbor).
 *
 * Returns the new state as one of the `LR_OSPF_NEIGHBOR_STATE_*`
 * constants, or 0 on a NULL handle.
 *
 * # Safety
 * `r` must be a valid OspfNeighbor handle.
 */
int32_t lr_ospf_neighbor_step_hello_seen(lr_ospf_neighbor_t r,
                                         uint32_t dr,
                                         uint32_t bdr,
                                         uint8_t priority);

/**
 * Drive the FSM with `AdjOk` (RFC 2328 §10.4 — decide whether to
 * become adjacent). `proceed` is 1 to start adjacency, 0 to break it.
 *
 * # Safety
 * See [`lr_ospf_neighbor_step_hello_seen`].
 */
int32_t lr_ospf_neighbor_step_adj_ok(lr_ospf_neighbor_t r, uint8_t proceed);

/**
 * Drive the FSM with `Kill` (RFC 2328 §10.1 — tear down the
 * adjacency). The neighbor returns to Down.
 *
 * # Safety
 * See [`lr_ospf_neighbor_step_hello_seen`].
 */
int32_t lr_ospf_neighbor_step_kill(lr_ospf_neighbor_t r);

/**
 * Construct one Router-LSA link entry (RFC 2328 §A.4.2). The
 * `link_kind` selects the variant; the field slots are then
 * interpreted per the variant:
 *
 * - `LR_OSPF_ROUTER_LSA_LINK_STUB`: `field1` = network address,
 *   `field2` = network mask, `metric` = interface cost.
 * - `LR_OSPF_ROUTER_LSA_LINK_POINT_TO_POINT`: `field1` = neighbor
 *   router-id, `field2` = our interface address, `metric` = cost.
 * - `LR_OSPF_ROUTER_LSA_LINK_TRANSIT`: `field1` = DR's IP interface
 *   address, `field2` = our interface address, `metric` = cost.
 * - `LR_OSPF_ROUTER_LSA_LINK_RAW`: `field1` = link_id, `field2` =
 *   link_data, `metric` = cost (no interpretation; used for virtual
 *   links). `field3` carries the link type byte (1=ptp, 2=transit,
 *   3=stub, 4=virtual).
 *
 * Returns `NULL` for an unknown `link_kind`.
 */
lr_ospf_router_lsa_link_t lr_ospf_router_lsa_link_new(int32_t link_kind,
                                                      uint32_t field1,
                                                      uint32_t field2,
                                                      uint8_t field3,
                                                      uint16_t metric);

/**
 * Drop a boxed `RouterLsaLink`. Safe to call with `NULL`.
 *
 * # Safety
 * `l` must have been produced by [`lr_ospf_router_lsa_link_new`] and
 * not already freed.
 */
void lr_ospf_router_lsa_link_free(lr_ospf_router_lsa_link_t l);

/**
 * Originate the router's own Router-LSA for an area (RFC 2328
 * §12.4.1). The `flags_byte` carries the V/E/B bits (use the
 * `LR_OSPF_ROUTER_LSA_FLAG_*` constants, OR'd together). `links` is
 * a flat array of `RouterLsaLink` handles; `count` is the link
 * count.
 *
 * `prev_seq` is the previous instance's sequence number (`NULL` to
 * start fresh at `INITIAL_SEQUENCE_NUMBER`).
 *
 * Writes a freshly-allocated `lr_ospf_lsa_box_t` to `*out` on success.
 * Returns 0 on success, `LR_ERR_OTHER` (-6) when the sequence space
 * is exhausted.
 *
 * # Safety
 * `links` must point to `count` valid `lr_ospf_router_lsa_link_t`
 * handles (they are borrowed, not consumed); `out` must point to
 * writable `lr_ospf_lsa_box_t`.
 */
int32_t lr_ospf_originate_router_lsa(uint32_t router_id,
                                     uint8_t flags_byte,
                                     const lr_ospf_router_lsa_link_t *links,
                                     uintptr_t count,
                                     const uint32_t *prev_seq,
                                     lr_ospf_lsa_box_t *out);

/**
 * Originate a Network-LSA for a transit broadcast/NBMA segment where
 * this router is the DR (RFC 2328 §12.4.2). `dr_router_id` is the
 * DR's OSPF router ID (the LSA's Advertising Router); `dr_addr` is
 * the DR's IP interface address on the segment (the Link State ID);
 * `mask` is the network's address mask; `attached_routers` is the
 * list of router-IDs of every router fully adjacent to the DR,
 * **including the DR itself**.
 *
 * # Safety
 * `attached_routers` must point to `count` readable `uint32_t`
 * values; `out` must point to writable `lr_ospf_lsa_box_t`.
 */
int32_t lr_ospf_originate_network_lsa(uint32_t dr_router_id,
                                      uint32_t dr_addr,
                                      uint32_t mask,
                                      const uint32_t *attached_routers,
                                      uintptr_t count,
                                      const uint32_t *prev_seq,
                                      lr_ospf_lsa_box_t *out);

lr_ospf_retransmit_t lr_ospf_retransmit_new(void);

void lr_ospf_retransmit_free(lr_ospf_retransmit_t r);

uintptr_t lr_ospf_retransmit_len(lr_ospf_retransmit_t r);

uint8_t lr_ospf_retransmit_is_empty(lr_ospf_retransmit_t r);

uint8_t lr_ospf_retransmit_contains(lr_ospf_retransmit_t r,
                                    uint16_t ls_type,
                                    uint32_t ls_id,
                                    uint32_t adv_router);

int32_t lr_ospf_retransmit_record_flood(lr_ospf_retransmit_t r,
                                        lr_ospf_lsa_box_t lsa,
                                        uint64_t now_ms);

uint8_t lr_ospf_retransmit_remove(lr_ospf_retransmit_t r,
                                  uint16_t ls_type,
                                  uint32_t ls_id,
                                  uint32_t adv_router);

void lr_ospf_retransmit_clear(lr_ospf_retransmit_t r);

/**
 * Run the RFC 2328 §16.1 intra-area SPF on `lsdb` rooted at
 * `router_id`. Returns a new `lr_ospf_spf_result_t` on success, NULL
 * on a NULL LSDB.
 *
 * # Safety
 * `lsdb` must be a valid LSDB handle.
 */
lr_ospf_spf_result_t lr_ospf_spf_run(lr_ospf_lsdb_t lsdb, uint32_t router_id);

/**
 * Drop a boxed `SpfResult`. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been produced by `lr_ospf_spf_run` and not already
 * freed.
 */
void lr_ospf_spf_result_free(lr_ospf_spf_result_t r);

/**
 * Total route count in a v2 `SpfResult` — stub networks plus transit
 * networks. Returns 0 on a NULL handle.
 *
 * # Safety
 * `r` must be a valid SpfResult handle.
 */
uintptr_t lr_ospf_spf_route_count(lr_ospf_spf_result_t r);

/**
 * Read one route by index. Indices 0..stub_count are stub networks;
 * the rest are transit networks. Writes the route's fields to
 * `*out`. Returns 0 on success, `LR_ERR_NULL` on a NULL result,
 * `LR_ERR_INVALID_HANDLE` (-2) on out-of-range.
 *
 * # Safety
 * `r` must be a valid SpfResult handle. `out` must point to a
 * writable `lr_ospf_spf_route_t`.
 */
int32_t lr_ospf_spf_route_at(lr_ospf_spf_result_t r,
                             uintptr_t index,
                             struct lr_ospf_spf_route_t *out);

/**
 * Number of inter-area summary routes derived from summary-LSAs
 * (RFC 2328 §16.2 — computed on top of an intra-area SPF result).
 * Returns 0 on a NULL handle.
 *
 * # Safety
 * `r` must be a valid SpfResult handle.
 */
uintptr_t lr_ospf_spf_summary_count(lr_ospf_lsdb_t lsdb, lr_ospf_spf_result_t r);

/**
 * Read one inter-area summary route by index. Computes
 * `summary_routes(lsdb, result)` and indexes into it. Returns 0 on
 * success, `LR_ERR_NULL` on a NULL LSDB or result,
 * `LR_ERR_INVALID_HANDLE` (-2) on out-of-range.
 *
 * # Safety
 * `lsdb` and `r` must be valid handles. `out` must point to a
 * writable `lr_ospf_spf_route_t`.
 */
int32_t lr_ospf_spf_summary_at(lr_ospf_lsdb_t lsdb,
                               lr_ospf_spf_result_t r,
                               uintptr_t index,
                               struct lr_ospf_spf_route_t *out);

/**
 * Run the RFC 5340 §4.8 intra-area SPF on a v3 LSDB rooted at
 * `router_id`. Returns a new `lr_ospf_spf_v3_result_t` on success,
 * NULL on a NULL LSDB.
 *
 * # Safety
 * `lsdb` must be a valid LSDB handle.
 */
lr_ospf_spf_v3_result_t lr_ospf_spf_v3_run(lr_ospf_lsdb_t lsdb, uint32_t router_id);

/**
 * Run the RFC 8362 Extended-LSA form of the v3 SPF (RFC 8362 §4).
 *
 * # Safety
 * See [`lr_ospf_spf_v3_run`].
 */
lr_ospf_spf_v3_result_t lr_ospf_spf_v3_extended_run(lr_ospf_lsdb_t lsdb, uint32_t router_id);

/**
 * Drop a boxed v3 `SpfResultV3`. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been produced by `lr_ospf_spf_v3_run` /
 * `_v3_extended_run` and not already freed.
 */
void lr_ospf_spf_v3_result_free(lr_ospf_spf_v3_result_t r);

/**
 * Total route count in a v3 `SpfResultV3`. Returns 0 on a NULL
 * handle.
 *
 * # Safety
 * `r` must be a valid SpfResultV3 handle.
 */
uintptr_t lr_ospf_spf_v3_route_count(lr_ospf_spf_v3_result_t r);

/**
 * Read one v3 route by index.
 *
 * # Safety
 * `r` must be a valid SpfResultV3 handle. `out` must point to a
 * writable `lr_ospf_spf_route_t`.
 */
int32_t lr_ospf_spf_v3_route_at(lr_ospf_spf_v3_result_t r,
                                uintptr_t index,
                                struct lr_ospf_spf_route_t *out);

/**
 * Number of inter-area summary routes on a v3 result (RFC 5340
 * §4.8 — computed on top of an intra-area v3 SPF result).
 *
 * # Safety
 * `lsdb` and `r` must be valid handles.
 */
uintptr_t lr_ospf_spf_v3_summary_count(lr_ospf_lsdb_t lsdb, lr_ospf_spf_v3_result_t r);

/**
 * Read one v3 inter-area summary route by index.
 *
 * # Safety
 * See [`lr_ospf_spf_v3_summary_count`]. `out` must point to a
 * writable `lr_ospf_spf_route_t`.
 */
int32_t lr_ospf_spf_v3_summary_at(lr_ospf_lsdb_t lsdb,
                                  lr_ospf_spf_v3_result_t r,
                                  uintptr_t index,
                                  struct lr_ospf_spf_route_t *out);

/**
 * Number of SRv6 locator routes on a v3 result (RFC 9513 §5 —
 * locator routes projected from the LSDB alongside the regular
 * intra-area SPF).
 *
 * # Safety
 * `r` must be a valid SpfResultV3 handle.
 */
uintptr_t lr_ospf_spf_v3_locator_count(lr_ospf_spf_v3_result_t r);

/**
 * Read one v3 SRv6 locator route by index. The route carries the
 * locator prefix + the algorithm + the metric + the next hop + the
 * advertising router (RFC 9513 §5.1). The locator route is exposed
 * through the same `lr_ospf_spf_route_t` shape, with `metric` and
 * `next_hop` populated from the locator projection.
 *
 * # Safety
 * `r` must be a valid SpfResultV3 handle. `out` must point to a
 * writable `lr_ospf_spf_route_t`.
 */
int32_t lr_ospf_spf_v3_locator_at(lr_ospf_spf_v3_result_t r,
                                  uintptr_t index,
                                  struct lr_ospf_spf_route_t *out);

/**
 * Open the platform's native route-table backend.
 *
 * On Linux this opens a `NETLINK_ROUTE` socket; on the BSDs/macOS a
 * `route(4)` socket; on Windows IP Helper. Everywhere else (or when the
 * OS denies the syscall) it returns `NULL` and sets the last-error
 * string — call [`lr_last_error`] for details.
 *
 * Returns a non-NULL handle on success.
 */
lr_osroute_t lr_osroute_connect(void);

/**
 * Open the stub backend — always succeeds; every operation returns
 * `LR_ERR_OTHER` with the documented stub message. Useful for testing
 * the FFI surface on platforms without a kernel route table.
 */
lr_osroute_t lr_osroute_connect_stub(void);

/**
 * Returns the human-readable backend name compiled in (e.g.
 * `"linux-rtnetlink"`, `"freebsd-route-socket"`, `"windows-ip-helper"`,
 * `"stub"`). The pointer is valid for the lifetime of the process —
 * do not free it. Returns `NULL` only on a panic.
 */
const char *lr_osroute_platform_name(void);

/**
 * Add a route: "to reach `prefix`, send via `next_hop` on `if_index`".
 * Returns 0 on success, negative on error:
 * - `LR_ERR_NULL` (-1): null handle / null prefix.
 * - `LR_ERR_INVALID_HANDLE` (-2): malformed prefix length.
 * - `LR_ERR_OTHER` (-6): backend error (see `lr_last_error`).
 * - `LR_ERR_PANIC` (-4): panic.
 *
 * # Safety
 * `t` must be a valid handle. `prefix` must point to a readable
 * `lr_prefix_t`. `next_hop` (when non-null) must point to 4 (IPv4) or
 * 16 (IPv6) readable bytes.
 */
int32_t lr_osroute_add_route(lr_osroute_t t,
                             const struct lr_prefix_t *prefix,
                             const uint8_t *next_hop,
                             uintptr_t next_hop_len,
                             uint32_t if_index);

/**
 * Add a route carrying the originating protocol's tag — the `RTPROT_*` /
 * `RouteProtocol*` kernel identifier shown by `ip route` / `route print`
 * and `lr routes list`. Backends that cannot tag fall back to
 * [`lr_osroute_add_route`].
 *
 * `protocol` is one of the `LR_PROTO_*` constants (see `lr_ffi.h`).
 *
 * # Safety
 * See [`lr_osroute_add_route`].
 */
int32_t lr_osroute_add_route_tagged(lr_osroute_t t,
                                    const struct lr_prefix_t *prefix,
                                    const uint8_t *next_hop,
                                    uintptr_t next_hop_len,
                                    uint32_t if_index,
                                    int32_t protocol);

/**
 * Add a *blackhole* (discard) route: packets matching `prefix` are
 * silently dropped by the kernel.
 *
 * # Safety
 * `t` must be a valid handle. `prefix` must point to a readable
 * `lr_prefix_t`.
 */
int32_t lr_osroute_add_blackhole_route(lr_osroute_t t, const struct lr_prefix_t *prefix);

/**
 * Delete a route matching the prefix.
 *
 * # Safety
 * See [`lr_osroute_add_blackhole_route`].
 */
int32_t lr_osroute_delete_route(lr_osroute_t t, const struct lr_prefix_t *prefix);

/**
 * Returns the number of routes currently in the kernel FIB.
 * Returns -1 (`LR_ERR_NULL`) on a NULL handle, or `LR_ERR_OTHER` (-6)
 * on a backend error.
 *
 * # Safety
 * `t` must be a valid handle.
 */
int64_t lr_osroute_list_routes_count(lr_osroute_t t);

/**
 * Dump all routes currently in the kernel FIB into `out` (caller-
 * allocated, at most `cap` entries). Returns the number of entries
 * written; a return value greater than `cap` means the buffer was too
 * small — call [`lr_osroute_list_routes_count`] first to size it.
 *
 * # Safety
 * `t` must be a valid handle. `out` (when non-null) must point to `cap`
 * writable `lr_kernel_route_t` values.
 */
int64_t lr_osroute_list_routes(lr_osroute_t t, struct lr_kernel_route_t *out, uintptr_t cap);

/**
 * Convenience: does the kernel currently have a route to this prefix?
 * Returns 1 (true), 0 (false), or a negative error code.
 *
 * # Safety
 * `t` must be a valid handle. `prefix` must point to a readable
 * `lr_prefix_t`.
 */
int32_t lr_osroute_has_route(lr_osroute_t t, const struct lr_prefix_t *prefix);

/**
 * Drop a boxed route-table handle. Safe to call with NULL.
 *
 * # Safety
 * `t` must have been produced by [`lr_osroute_connect`] or
 * [`lr_osroute_connect_stub`] and must not be used after this call.
 */
void lr_osroute_destroy(lr_osroute_t t);

/**
 * Construct a single-hop GTSM (RFC 5082 §4.1): TTL=255 both
 * directions. This is the standard configuration for directly
 * connected eBGP.
 */
struct lr_gtsm_t lr_gtsm_single_hop(void);

/**
 * Construct a multihop GTSM (RFC 5082 §4.2). `hops` must be in
 * `1..=254` (255 is single-hop; 0 is meaningless). Returns the
 * zero-default struct and sets the last-error string when `hops`
 * is out of range — callers that want to validate up front should
 * check the returned `outbound_ttl` is non-zero.
 */
struct lr_gtsm_t lr_gtsm_multihop(uint8_t hops);

/**
 * Construct a disabled GTSM (no TTL enforcement). Equivalent to the
 * default `lr_gtsm_t`.
 */
struct lr_gtsm_t lr_gtsm_disabled(void);

/**
 * Read the outbound TTL field. Returns 0 on a disabled GTSM.
 */
uint8_t lr_gtsm_outbound_ttl(struct lr_gtsm_t g);

/**
 * Read the minimum inbound TTL field. Returns 0 on a disabled GTSM.
 */
uint8_t lr_gtsm_min_ttl(struct lr_gtsm_t g);

/**
 * True when GTSM is effectively a no-op (both fields are zero).
 * Returns 1 (true) or 0 (false).
 */
uint8_t lr_gtsm_is_disabled(struct lr_gtsm_t g);

/**
 * Categorise the GTSM as one of the `LR_GTSM_MODE_*` constants.
 */
int32_t lr_gtsm_mode(struct lr_gtsm_t g);

/**
 * Construct a symmetric MKT (`send_id == recv_id`, the common case).
 * `id` is the KeyID placed in both directions; `key` points to
 * `key_len` raw key bytes (1..=80). Returns 0 on success and writes
 * the MKT to `*out`; returns `LR_ERR_NULL` (-1) on a null key/out
 * pointer, `LR_ERR_OTHER` (-6) when the key length is out of range.
 *
 * # Safety
 * `key` must point to `key_len` readable bytes (NULL only when
 * `key_len == 0`). `out` must point to a writable
 * `lr_tcp_ao_key_t`.
 */
int32_t lr_tcp_ao_key_symmetric(uint8_t id,
                                const uint8_t *key,
                                uintptr_t key_len,
                                struct lr_tcp_ao_key_t *out);

/**
 * Construct an MKT with distinct send/receive KeyIDs. Same contract
 * as [`lr_tcp_ao_key_symmetric`] but `send_id` and `recv_id` can
 * differ.
 *
 * # Safety
 * See [`lr_tcp_ao_key_symmetric`].
 */
int32_t lr_tcp_ao_key_new(uint8_t send_id,
                          uint8_t recv_id,
                          const uint8_t *key,
                          uintptr_t key_len,
                          struct lr_tcp_ao_key_t *out);

/**
 * Read the send_id / recv_id / key_len from an MKT. Returns 0 on
 * success, `LR_ERR_NULL` on a null key/out pointer.
 *
 * # Safety
 * `key` must point to a readable `lr_tcp_ao_key_t`. The three out
 * pointers must be non-null.
 */
int32_t lr_tcp_ao_key_read(const struct lr_tcp_ao_key_t *key,
                           uint8_t *out_send_id,
                           uint8_t *out_recv_id,
                           uintptr_t *out_key_len);

/**
 * Copy the raw key bytes from an MKT into `out_buf`. Writes at most
 * `cap` bytes; returns the total key length (>= 0) — a return value
 * greater than `cap` means the buffer was too small.
 *
 * # Safety
 * `key` must point to a readable `lr_tcp_ao_key_t`. `out_buf` (when
 * non-null) must point to `cap` writable bytes.
 */
int64_t lr_tcp_ao_key_copy(const struct lr_tcp_ao_key_t *key, uint8_t *out_buf, uintptr_t cap);

/**
 * Categorise a [`TcpAuth`] value as one of the `LR_TCP_AUTH_*`
 * constants.
 *
 * # Safety
 * `auth` must be a valid `lr_tcp_auth_t` pointer.
 */
int32_t lr_tcp_auth_kind(lr_tcp_auth_t auth);

/**
 * True (1) when the auth configuration is `None` (plain TCP).
 *
 * # Safety
 * `auth` must be a valid `lr_tcp_auth_t` pointer.
 */
uint8_t lr_tcp_auth_is_none(lr_tcp_auth_t auth);

/**
 * Construct a `TcpAuth::None` (plain TCP, no authentication). The
 * returned handle is owned by the caller; free with
 * [`lr_tcp_auth_free`].
 */
lr_tcp_auth_t lr_tcp_auth_new_none(void);

/**
 * Construct a `TcpAuth::Md5` (RFC 2385) with one shared secret.
 * `key` points to `key_len` raw key bytes (1..=80). Returns NULL on
 * error (the last-error string is set).
 *
 * # Safety
 * `key` must point to `key_len` readable bytes (NULL only when
 * `key_len == 0`).
 */
lr_tcp_auth_t lr_tcp_auth_new_md5(const uint8_t *key, uintptr_t key_len);

/**
 * Construct a `TcpAuth::Ao` (RFC 5925). `keys` is an array of
 * `lr_tcp_ao_key_t` (at least one entry required). `algorithm` is
 * one of the `LR_TCP_AO_ALG_*` constants. `mac_len` is the MAC
 * length in bytes (0 selects the algorithm default). Returns NULL
 * on error.
 *
 * # Safety
 * `keys` must point to `keys_count` readable `lr_tcp_ao_key_t`
 * values. The caller retains ownership of the array; the FFI copies
 * the values into a Rust `Vec<TcpAoKey>`.
 */
lr_tcp_auth_t lr_tcp_auth_new_ao(const struct lr_tcp_ao_key_t *keys,
                                 uintptr_t keys_count,
                                 int32_t algorithm,
                                 uint8_t mac_len);

/**
 * Drop a boxed `TcpAuth`. Safe to call with NULL.
 *
 * # Safety
 * `auth` must have been produced by `lr_tcp_auth_new_*` and not
 * already freed.
 */
void lr_tcp_auth_free(lr_tcp_auth_t auth);

/**
 * Install one redistribution pipe on the router.
 *
 * `source` / `target` are [`LrProtocol`] values, `metric_policy` a
 * [`LrMetricPolicy`]. `has_tag` gates `tag` (any non-zero installs
 * the tag). `allow` / `allow_count` carry an optional allow-list of
 * prefixes (NULL / 0 = redistribute everything). Returns 0 on
 * success, -1 on a null argument, -2 on an invalid router handle,
 * -3 on a malformed argument (unknown protocol id, bad prefix
 * length), and [`LR_ERR_PANIC`] if the body panics.
 *
 * # Safety
 * `r` must be a live router handle. `allow` (when non-null) must
 * point to `allow_count` readable `lr_prefix_t` values.
 */
int32_t lr_router_add_redistribution_pipe(lr_router_t r,
                                          int32_t source,
                                          int32_t target,
                                          int32_t metric_policy,
                                          uint32_t metric,
                                          int32_t has_tag,
                                          uint32_t tag,
                                          const struct lr_prefix_t *allow,
                                          uintptr_t allow_count);

/**
 * Register an RFC 4271 §9.2.2.2 aggregate. The aggregate is
 * originated while a more-specific exists and withdrawn when the
 * last one disappears. Returns 0 on success, -1 / -2 / -3 on
 * null / invalid-handle / malformed-prefix.
 *
 * # Safety
 * `r` must be a live router handle; `prefix` must be a readable
 * `lr_prefix_t`.
 */
int32_t lr_router_add_aggregate(lr_router_t r, const struct lr_prefix_t *prefix);

/**
 * Withdraw a previously registered aggregate. Removing an unknown
 * prefix is a no-op that still returns 0 (the router treats it the
 * same way).
 *
 * # Safety
 * See [`lr_router_add_aggregate`].
 */
int32_t lr_router_remove_aggregate(lr_router_t r, const struct lr_prefix_t *prefix);

/**
 * Install the RFC 2439 damping import hook with the supplied
 * tunables and return a shared [`lr_damping_t`] handle. The embedder
 * drives decay with [`lr_damping_decay`] (the in-process analogue of
 * the daemon's `lr-damping-decay` thread) and frees the handle with
 * [`lr_damping_destroy`]. Installing damping twice replaces nothing —
 * the second hook simply chains after the first; call this once per
 * router.
 *
 * Returns NULL on null/invalid arguments (the last-error string says
 * which) and the handle otherwise.
 *
 * # Safety
 * `r` must be a live router handle; `cfg` must be a readable
 * `lr_damping_config_t`.
 */
lr_damping_t lr_router_set_damping(lr_router_t r, const struct lr_damping_config_t *cfg);

/**
 * Drive one damping decay pass at wall-clock `now_s` (seconds).
 * Returns the number of prefixes that re-emerged from suppression
 * (>= 0), or negative error codes on null / invalid handles.
 *
 * # Safety
 * `d` must be a live damping handle from [`lr_router_set_damping`].
 */
int32_t lr_damping_decay(struct OpaqueDamping *d, uint64_t now_s);

/**
 * Free a damping handle. The hook installed on the router keeps its
 * own `Arc`, so damping continues until the router is destroyed;
 * destroying the handle only releases the embedder's decay access.
 *
 * # Safety
 * `d` must be null or a handle returned by [`lr_router_set_damping`]
 * that has not been destroyed yet, and must not be used afterwards.
 */
void lr_damping_destroy(struct OpaqueDamping *d);

/**
 * Create a route handle for an IPv4 prefix. `protocol` is an
 * [`LrProtocol`] id. Returns NULL on a malformed prefix length or
 * unknown protocol id (the last-error string says which).
 *
 * # Safety
 * `octets` must point to 4 readable bytes.
 */
lr_route_t lr_route_new_v4(const uint8_t *octets, uint8_t prefix_len, int32_t protocol);

/**
 * Create a route handle for an IPv6 prefix. See
 * [`lr_route_new_v4`] for the contract.
 *
 * # Safety
 * `octets` must point to 16 readable bytes.
 */
lr_route_t lr_route_new_v6(const uint8_t *octets, uint8_t prefix_len, int32_t protocol);

/**
 * Free a route handle. NULL is a no-op.
 *
 * # Safety
 * `route` must be null or a handle returned by `lr_route_new_*` that
 * has not been freed yet, and must not be used afterwards.
 */
void lr_route_free(lr_route_t route);

/**
 * Set the route's next hop (RFC 4271 §5.1.3). `addr` carries the
 * IPv4 octets in the first four bytes when `is_ipv6` is 0. Returns
 * 0, -1 on a null argument.
 *
 * # Safety
 * `addr` must point to 4 (v4) / 16 (v6) readable bytes.
 */
int32_t lr_route_set_next_hop(lr_route_t route, const uint8_t *addr, int32_t is_ipv6);

/**
 * Read the route's next hop into `out` (16 bytes, IPv4 in the first
 * four) and its family into `out_is_ipv6`. Returns 0 when present,
 * 1 when absent, -1 on a null argument.
 *
 * # Safety
 * `out` must be writable for 16 bytes; `out_is_ipv6` writable for one
 * `i32`.
 */
int32_t lr_route_next_hop(lr_route_t route, uint8_t *out, int32_t *out_is_ipv6);

/**
 * Set the BGP LOCAL_PREF (RFC 4271 §5.1.5). Returns 0 / -1.
 *
 * # Safety
 * `route` must be a live handle.
 */
int32_t lr_route_set_local_pref(lr_route_t route, uint32_t value);

/**
 * Read LOCAL_PREF into `out`. Returns 0 present, 1 absent, -1 null.
 *
 * # Safety
 * `out` must be writable.
 */
int32_t lr_route_local_pref(lr_route_t route, uint32_t *out);

/**
 * Set the BGP MULTI_EXIT_DISC (RFC 4271 §4.2.4). 0 / -1.
 *
 * # Safety
 * `route` must be a live handle.
 */
int32_t lr_route_set_med(lr_route_t route, uint32_t value);

/**
 * Read MULTI_EXIT_DISC. 0 present, 1 absent, -1 null.
 *
 * # Safety
 * `out` must be writable.
 */
int32_t lr_route_med(lr_route_t route, uint32_t *out);

/**
 * Set the BGP ORIGIN (RFC 4271 §5.1.1): [`LR_ORIGIN_IGP`],
 * [`LR_ORIGIN_EGP`] or [`LR_ORIGIN_INCOMPLETE`]. Returns 0, -1 null,
 * -3 unknown origin value.
 *
 * # Safety
 * `route` must be a live handle.
 */
int32_t lr_route_set_origin(lr_route_t route, uint8_t origin);

/**
 * Read ORIGIN into `out`. 0 present, 1 absent, -1 null.
 *
 * # Safety
 * `out` must be writable.
 */
int32_t lr_route_origin(lr_route_t route, uint8_t *out);

/**
 * Replace the AS_PATH with a flat sequence (RFC 4271 §4.3). An empty
 * sequence drops the attribute. 0 ok, -1 null.
 *
 * # Safety
 * `asns` must point to `count` readable `u32`s when non-null.
 */
int32_t lr_route_set_as_path(lr_route_t route, const uint32_t *asns, uintptr_t count);

/**
 * Read the AS_PATH's flat sequence. Call with `out = NULL` to get the
 * required length; with a buffer, returns the number of ASes written.
 * Negative on null handle / buffer smaller than needed.
 *
 * # Safety
 * `out` (when non-null) must be writable for `cap` `u32`s.
 */
int64_t lr_route_as_path(lr_route_t route, uint32_t *out, uintptr_t cap);

/**
 * Append one standard community (RFC 1997 §4). The ASN must fit 16
 * bits — 4-octet-AS communities ride LARGE_COMMUNITIES (RFC 8092).
 * 0 ok, -1 null, -3 ASN > 0xFFFF.
 *
 * # Safety
 * `route` must be a live handle.
 */
int32_t lr_route_add_community(lr_route_t route, uint32_t asn, uint16_t value);

/**
 * Replace the whole standard COMMUNITIES attribute from packed
 * `asn << 16 | value` items. An empty set drops the attribute.
 *
 * # Safety
 * `items` must point to `count` readable `u64`s when non-null.
 */
int32_t lr_route_set_communities(lr_route_t route, const uint64_t *items, uintptr_t count);

/**
 * Read the standard communities as packed `asn << 16 | value`.
 * `out = NULL` → required length; otherwise the count written.
 *
 * # Safety
 * `out` (when non-null) must be writable for `cap` `u64`s.
 */
int64_t lr_route_communities(lr_route_t route, uint64_t *out, uintptr_t cap);

/**
 * Append one large community (RFC 8092).
 *
 * # Safety
 * `route` must be a live handle.
 */
int32_t lr_route_add_large_community(lr_route_t route,
                                     uint32_t global_admin,
                                     uint32_t local_data1,
                                     uint32_t local_data2);

/**
 * Replace the whole LARGE_COMMUNITIES attribute from flat triples.
 *
 * # Safety
 * `triples` must point to `count * 3` readable `u32`s when non-null.
 */
int32_t lr_route_set_large_communities(lr_route_t route, const uint32_t *triples, uintptr_t count);

/**
 * Read the large communities as flat triples. `out = NULL` →
 * required `u32` count (3 * entries); otherwise the count written.
 *
 * # Safety
 * `out` (when non-null) must be writable for `cap` `u32`s.
 */
int64_t lr_route_large_communities(lr_route_t route, uint32_t *out, uintptr_t cap);

/**
 * Append one extended community (RFC 4360).
 *
 * # Safety
 * `route` must be a live handle.
 */
int32_t lr_route_add_ext_community(lr_route_t route,
                                   uint8_t kind,
                                   uint8_t subtype,
                                   uint32_t global,
                                   uint16_t local);

/**
 * Replace the whole EXTENDED_COMMUNITIES attribute.
 *
 * # Safety
 * `items` must point to `count` readable `lr_ext_comm_t`s when
 * non-null.
 */
int32_t lr_route_set_ext_communities(lr_route_t route,
                                     const struct lr_ext_comm_t *items,
                                     uintptr_t count);

/**
 * Read the extended communities. `out = NULL` → required length,
 * otherwise the count written.
 *
 * # Safety
 * `out` (when non-null) must be writable for `cap` `lr_ext_comm_t`s.
 */
int64_t lr_route_ext_communities(lr_route_t route, struct lr_ext_comm_t *out, uintptr_t cap);

/**
 * Set the route's metric (the cross-protocol preference metric).
 * 0 / -1.
 *
 * # Safety
 * `route` must be a live handle.
 */
int32_t lr_route_set_metric(lr_route_t route, uint32_t value);

/**
 * Read the route's metric. 0 / -1.
 *
 * # Safety
 * `out` must be writable.
 */
int32_t lr_route_metric(lr_route_t route, uint32_t *out);

/**
 * Set the operator route tag (`None` when `has_tag` is 0). 0 / -1.
 *
 * # Safety
 * `route` must be a live handle.
 */
int32_t lr_route_set_tag(lr_route_t route, int32_t has_tag, uint32_t tag);

/**
 * Read the route tag. 0 present, 1 absent, -1 null.
 *
 * # Safety
 * `out` must be writable.
 */
int32_t lr_route_tag(lr_route_t route, uint32_t *out);

/**
 * Create an empty prefix-list. NULL on panic.
 */
lr_prefix_list_t lr_prefix_list_new(void);

/**
 * Free a prefix-list. NULL is a no-op.
 *
 * # Safety
 * `list` must be null or a handle from `lr_prefix_list_new` that has
 * not been freed or consumed by `lr_resolver_add_prefix_list`.
 */
void lr_prefix_list_free(lr_prefix_list_t list);

/**
 * Append one entry: `prefix` with the ge/le length window (FRR
 * `ge`/`le`; `le = 255` means no upper bound) and `permit` (non-zero
 * = permit). First matching entry decides; no match denies.
 * 0 ok, -1 null, -3 malformed prefix.
 *
 * # Safety
 * `list` must be a live handle; `prefix` a readable `lr_prefix_t`.
 */
int32_t lr_prefix_list_add(lr_prefix_list_t list,
                           const struct lr_prefix_t *prefix,
                           uint8_t ge,
                           uint8_t le,
                           int32_t permit);

/**
 * Evaluate the list against `prefix`: 1 = permit, 0 = deny (implicit
 * deny included), -1 null.
 *
 * # Safety
 * `list` must be a live handle; `prefix` a readable `lr_prefix_t`.
 */
int32_t lr_prefix_list_match(lr_prefix_list_t list, const struct lr_prefix_t *prefix);

/**
 * Create an empty route-map. NULL on panic.
 */
lr_route_map_t lr_route_map_new(void);

/**
 * Free a route-map. NULL is a no-op.
 *
 * # Safety
 * `map` must be null or a handle from `lr_route_map_new` that has not
 * been freed.
 */
void lr_route_map_free(lr_route_map_t map);

/**
 * Append one entry: all `matches` must hold, then all `sets` apply
 * and `verdict` decides ([`LR_VERDICT_CONTINUE`] falls through to the
 * next entry). Entries are tried in insertion order. 0 ok, -1 null,
 * -3 malformed match/set or prefix length.
 *
 * # Safety
 * `map` must be a live handle; the arrays readable for `n_matches` /
 * `n_sets` items when non-null.
 */
int32_t lr_route_map_add_entry(lr_route_map_t map,
                               const struct lr_match_t *matches,
                               uintptr_t n_matches,
                               const struct lr_set_t *sets,
                               uintptr_t n_sets,
                               int32_t verdict);

/**
 * FRR route-map evaluation over a live route handle: the first
 * matching entry applies its sets and its verdict lands in `out`
 * ([`LR_EVAL_PERMIT`] / [`LR_EVAL_DENY`] / [`LR_EVAL_FALLTHROUGH`]).
 * Mutations are visible to subsequent `lr_route_*` reads.
 * 0 ok, -1 null, -2 invalid handle.
 *
 * `resolver` may be NULL: then every list-backed match fails
 * (fail-closed, FRR unknown-list semantics).
 *
 * # Safety
 * `map` / `route` must be live handles; `resolver` null or live.
 */
int32_t lr_route_map_evaluate(lr_route_map_t map,
                              lr_route_t route,
                              lr_resolver_t resolver,
                              int32_t *out);

/**
 * Create an empty policy resolver. NULL on panic.
 */
lr_resolver_t lr_resolver_new(void);

/**
 * Free a resolver. Registered policy objects go with it.
 *
 * # Safety
 * `resolver` must be null or a handle from `lr_resolver_new` that has
 * not been freed.
 */
void lr_resolver_free(lr_resolver_t resolver);

/**
 * Register the prefix-list under `name` (NUL-terminated). The list is
 * COPIED into the resolver; the caller keeps ownership of the handle.
 * Returns the numeric list id for `lr_match_t.list_id` (>= 0), or
 * -1/-3 on null/malformed.
 *
 * # Safety
 * `resolver` must be live; `name` a readable NUL-terminated string;
 * `list` a live handle.
 */
int32_t lr_resolver_add_prefix_list(lr_resolver_t resolver,
                                    const char *name,
                                    lr_prefix_list_t list);

/**
 * Register an AS-path access-list (FRR dialect) under `name`. Returns
 * the list id, or -1/-3.
 *
 * # Safety
 * `resolver` must be live; `filters` readable for `count` items, each
 * `pattern` a readable NUL-terminated string.
 */
int32_t lr_resolver_add_as_path_list(lr_resolver_t resolver,
                                     const char *name,
                                     const struct lr_as_path_filter_t *filters,
                                     uintptr_t count);

/**
 * Register a standard community list (RFC 1997) under `name`. Returns
 * the list id, or -1/-3.
 *
 * # Safety
 * `resolver` must be live; `entries` readable for `count` items, each
 * `communities` array readable for its `count`.
 */
int32_t lr_resolver_add_community_list(lr_resolver_t resolver,
                                       const char *name,
                                       const struct lr_community_entry_t *entries,
                                       uintptr_t count);

/**
 * Construct a `SafetyNet` for the given local AS (RFC 4271 §9.1.4
 * safety checks). The local AS is used for AS-path loop detection.
 *
 * Returns NULL on a panic.
 */
lr_safety_net_t lr_safety_net_new(uint32_t local_as);

/**
 * Set the local source address (for martian / source-alias checks).
 * Returns a NEW handle (the input handle is consumed and freed).
 *
 * # Safety
 * `r` must be a valid SafetyNet handle. `addr_v4` is the 4-byte IPv4
 * address (NULL when IPv6); `addr_v6` is the 16-byte IPv6 address
 * (NULL when IPv4).
 */
lr_safety_net_t lr_safety_net_with_local_addr(lr_safety_net_t r,
                                              const uint8_t *addr_v4,
                                              const uint8_t *addr_v6);

/**
 * Check one route against the safety net. `is_ebgp` selects the
 * eBGP-specific checks (RFC 4271 §9.1.2 — the AS_PATH must not
 * contain the local AS, the NEXT_HOP must not be the local address,
 * etc.).
 *
 * Returns 0 when the route passes, 1 when a violation was detected
 * (the violation is recorded in the last-error string), negative on
 * error.
 *
 * # Safety
 * `r` must be a valid SafetyNet handle. `route` must be a valid
 * route handle.
 */
int32_t lr_safety_net_check(lr_safety_net_t r, lr_route_t route, uint8_t is_ebgp);

/**
 * Drop a boxed SafetyNet. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been produced by `lr_safety_net_new` and not already
 * freed.
 */
void lr_safety_net_free(lr_safety_net_t r);

/**
 * Read the global kill switch from the safety net's config. Returns
 * 1 when enabled, 0 when disabled, `LR_ERR_NULL` (-1) on a NULL handle.
 *
 * # Safety
 * `r` must be a valid SafetyNet handle.
 */
int32_t lr_safety_net_config_enabled(lr_safety_net_t r);

/**
 * Set the global kill switch on the safety net's config.
 *
 * # Safety
 * `r` must be a valid SafetyNet handle.
 */
int32_t lr_safety_net_config_set_enabled(lr_safety_net_t r, uint8_t enabled);

/**
 * Read one of the boolean toggles on the safety net's config. `field`
 * selects which:
 * - 0: reject_as_loop
 * - 1: reject_invalid_next_hop
 * - 2: reject_empty_as_path_ebgp
 * - 3: reject_invalid_origin
 * - 4: reject_excessive_as_loop
 * - 5: reject_oversized_as_path
 * - 6: reject_martian_prefix
 * - 7: reject_oversized_local_pref
 * - 8: reject_martian_v4
 * - 9: reject_martian_v6
 *
 * Returns the toggle value (0/1), `LR_ERR_NULL` (-1) on a NULL
 * handle, `LR_ERR_OTHER` (-6) on an unknown field id.
 *
 * # Safety
 * `r` must be a valid SafetyNet handle.
 */
int32_t lr_safety_net_config_get_bool(lr_safety_net_t r, int32_t field);

/**
 * Set one of the boolean toggles on the safety net's config. `field`
 * selects which (see [`lr_safety_net_config_get_bool`]); `value` is
 * the new toggle value (0 or 1).
 *
 * # Safety
 * `r` must be a valid SafetyNet handle.
 */
int32_t lr_safety_net_config_set_bool(lr_safety_net_t r, int32_t field, uint8_t value);

/**
 * Read one of the integer tunables on the safety net's config. `field`
 * selects which:
 * - 0: max_as_path_loops (u8)
 * - 1: max_as_path_length (usize)
 * - 2: max_local_pref (u32)
 *
 * Returns the tunable value as a u64 (zero-extended), `LR_ERR_NULL`
 * (-1) on a NULL handle, `LR_ERR_OTHER` (-6) on an unknown field id.
 *
 * # Safety
 * `r` must be a valid SafetyNet handle.
 */
uint64_t lr_safety_net_config_get_u64(lr_safety_net_t r, int32_t field);

/**
 * Set one of the integer tunables on the safety net's config. `field`
 * selects which (see [`lr_safety_net_config_get_u64`]); `value` is
 * the new tunable value (truncated to the field's native width).
 *
 * # Safety
 * `r` must be a valid SafetyNet handle.
 */
int32_t lr_safety_net_config_set_u64(lr_safety_net_t r, int32_t field, uint64_t value);

/**
 * Check one route against the safety net and surface the violation
 * discriminant when one is detected. Returns 0 when the route passes,
 * a positive `LR_SAFETY_VIOLATION_*` constant when a violation was
 * detected (the human-readable message is recorded in the last-error
 * string), `LR_ERR_NULL` (-1) on a NULL handle, `LR_ERR_PANIC` (-4)
 * on a panic.
 *
 * # Safety
 * `r` must be a valid SafetyNet handle. `route` must be a valid
 * route handle.
 */
int32_t lr_safety_net_check_violation(lr_safety_net_t r, lr_route_t route, uint8_t is_ebgp);

/**
 * Look up a list id by name and kind. Returns the list id (>= 1)
 * when found, 0 when the name is not registered, negative on error.
 *
 * `kind` is one of the `LR_LIST_KIND_*` constants.
 *
 * # Safety
 * `r` must be a valid resolver handle. `name` must be a
 * NUL-terminated C string.
 */
int32_t lr_resolver_list_id(lr_resolver_t r, int32_t kind, const char *name);

/**
 * Count the route-maps registered on the resolver. Returns 0 on a
 * NULL handle.
 *
 * # Safety
 * `r` must be a valid resolver handle.
 */
uintptr_t lr_resolver_route_map_count(lr_resolver_t r);

/**
 * Enumerate the route-map names registered on the resolver. Writes
 * up to `cap` NUL-terminated UTF-8 strings into `out_buf` (each
 * pointer points into a single contiguous buffer of `cap` bytes
 * total). Writes the matching string offsets into `out_offsets` /
 * `out_lens`. Returns the total number of route-maps (>= 0) — a
 * return value greater than `cap` means the buffer was too small.
 *
 * The caller should size the buffer by calling
 * [`lr_resolver_route_map_count`] first, then call this with a buffer
 * of `count * 64` bytes (route-map names are bounded by 64 chars in
 * practice).
 *
 * # Safety
 * `r` must be a valid resolver handle. `out_buf` (when non-null)
 * must point to `cap` writable bytes. `out_offsets` / `out_lens`
 * (when non-null) must point to `cap` writable `uintptr_t` values.
 */
uintptr_t lr_resolver_route_map_names(lr_resolver_t r,
                                      char *out_buf,
                                      uintptr_t *out_offsets,
                                      uintptr_t *out_lens,
                                      uintptr_t cap);

/**
 * Append an entry to an existing route-map. Returns 0 on success,
 * `LR_ERR_NULL` on a NULL resolver / map handle, `LR_ERR_OTHER` (-6)
 * when the named route-map does not exist.
 *
 * # Safety
 * `r` must be a valid resolver handle. `name` must be a
 * NUL-terminated C string. `map` must be a valid route-map handle.
 */
int32_t lr_resolver_push_route_map_entry(lr_resolver_t r, const char *name, lr_route_map_t map);

/**
 * Bind a route-map to a session's import path. Returns 0 on
 * success, `LR_ERR_NULL` on a NULL resolver, `LR_ERR_OTHER` (-6)
 * when the named route-map does not exist.
 *
 * # Safety
 * `r` must be a valid resolver handle. `map_name` must be a
 * NUL-terminated C string (NULL is treated as "no map").
 */
int32_t lr_policy_set_bind_import(lr_resolver_t r, uint64_t session, const char *map_name);

/**
 * Bind a route-map to a session's export path. Same contract as
 * [`lr_policy_set_bind_import`].
 *
 * # Safety
 * See [`lr_policy_set_bind_import`].
 */
int32_t lr_policy_set_bind_export(lr_resolver_t r, uint64_t session, const char *map_name);

/**
 * Validate the PolicySet's bindings — returns 0 when the set is
 * internally consistent, 1 when a binding references a route-map
 * that does not exist (the offending session + reason are recorded
 * in the last-error string), negative on error.
 *
 * # Safety
 * `r` must be a valid resolver handle.
 */
int32_t lr_policy_set_validate(lr_resolver_t r);

/**
 * Construct an empty Loc-RIB (RFC 4271 §9).
 */
lr_loc_rib_t lr_loc_rib_new(void);

/**
 * Drop a boxed Loc-RIB. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been produced by `lr_loc_rib_new` and not already
 * freed. Double-free is undefined behaviour.
 */
void lr_loc_rib_free(lr_loc_rib_t r);

/**
 * Install one path into the Loc-RIB (RFC 4271 §9.1, RFC 7911
 * path-id aware). The `route` handle is *consumed* — the caller
 * must not use it after this call.
 *
 * Returns 1 when the install actually changed the Loc-RIB (a new
 * path was added or an existing one replaced with non-identical
 * content); 0 for a byte-identical no-op (no generation bump).
 * Negative on error.
 *
 * # Safety
 * `r` must be a valid Loc-RIB handle. `route` must be a valid route
 * handle produced by `lr_route_new_v4` / `lr_route_new_v6`.
 */
int32_t lr_loc_rib_install(lr_loc_rib_t r, lr_route_t route);

/**
 * Uninstall a key (RFC 4271 §9.1 withdraw). Returns 1 when a route
 * was withdrawn, 0 when the key was not present.
 *
 * # Safety
 * `r` must be a valid Loc-RIB handle. `prefix` must be a readable
 * `lr_prefix_t`.
 */
int32_t lr_loc_rib_uninstall(lr_loc_rib_t r,
                             const struct lr_prefix_t *prefix,
                             uint16_t afi,
                             uint8_t safi,
                             const struct lr_prefix_t *source);

/**
 * Number of keys (prefixes) in the Loc-RIB. Returns 0 on a NULL handle.
 *
 * # Safety
 * `r` must be a valid Loc-RIB handle.
 */
uintptr_t lr_loc_rib_len(lr_loc_rib_t r);

/**
 * True when the Loc-RIB holds no keys. Returns 1 (true) on a NULL
 * handle (the safe default for "no routes to advertise").
 *
 * # Safety
 * See [`lr_loc_rib_len`].
 */
uint8_t lr_loc_rib_is_empty(lr_loc_rib_t r);

/**
 * Total number of stored paths (>= `len()` under RFC 7911 Add-Path).
 * Returns 0 on a NULL handle.
 *
 * # Safety
 * See [`lr_loc_rib_len`].
 */
uintptr_t lr_loc_rib_paths_len(lr_loc_rib_t r);

/**
 * Monotonic generation counter — callers can ask "what changed since
 * generation X?". Returns 0 on a NULL handle.
 *
 * # Safety
 * See [`lr_loc_rib_len`].
 */
uint64_t lr_loc_rib_generation(lr_loc_rib_t r);

/**
 * True when a route is present for the given key. Returns 0 on a NULL
 * handle or when the key is absent.
 *
 * # Safety
 * `r` must be a valid Loc-RIB handle. `prefix` must be a readable
 * `lr_prefix_t`.
 */
uint8_t lr_loc_rib_best_present(lr_loc_rib_t r,
                                const struct lr_prefix_t *prefix,
                                uint16_t afi,
                                uint8_t safi,
                                const struct lr_prefix_t *source);

/**
 * Read the best path for a key. Returns 0 on success and writes a
 * NEW `lr_route_t` handle (a *copy* of the Loc-RIB's internal route)
 * to `*out`. The caller owns the copy and must free it via
 * `lr_route_free`. Returns `LR_ERR_NULL` on a NULL Loc-RIB, 0 with
 * `*out = NULL` when the key is absent.
 *
 * # Safety
 * `r` must be a valid Loc-RIB handle. `prefix` and `out` must point
 * to writable memory.
 */
int32_t lr_loc_rib_best(lr_loc_rib_t r,
                        const struct lr_prefix_t *prefix,
                        uint16_t afi,
                        uint8_t safi,
                        const struct lr_prefix_t *source,
                        lr_route_t *out);

/**
 * Construct an empty Adj-RIB-In (RFC 4271 §9).
 */
lr_adj_rib_in_t lr_adj_rib_in_new(void);

/**
 * Drop a boxed Adj-RIB-In. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been produced by `lr_adj_rib_in_new` and not already
 * freed.
 */
void lr_adj_rib_in_free(lr_adj_rib_in_t r);

/**
 * Install one pre-policy route from `origin`. The `route` handle is
 * *consumed* — the caller must not use it after this call.
 *
 * `origin_peer` is the peer's session handle (the `RouteOrigin::peer`
 * field); `origin_proto` is the `RouteOrigin::proto` field (one of
 * the `LR_PROTO_*` constants).
 *
 * # Safety
 * `r` must be a valid Adj-RIB-In handle. `route` must be a valid route
 * handle.
 */
int32_t lr_adj_rib_in_feed(lr_adj_rib_in_t r,
                           uint64_t origin_peer,
                           int32_t origin_proto,
                           lr_route_t route);

/**
 * Withdraw one (origin, key, path-id) tuple. Returns 1 when a route
 * was withdrawn, 0 when no matching entry existed.
 *
 * # Safety
 * `r` must be a valid Adj-RIB-In handle. `prefix` must be readable.
 */
int32_t lr_adj_rib_in_withdraw(lr_adj_rib_in_t r,
                               uint64_t origin_peer,
                               int32_t origin_proto,
                               const struct lr_prefix_t *prefix,
                               uint16_t afi,
                               uint8_t safi,
                               const struct lr_prefix_t *source,
                               uint32_t path_id);

/**
 * Total number of stored routes. Returns 0 on a NULL handle.
 *
 * # Safety
 * `r` must be a valid Adj-RIB-In handle.
 */
uintptr_t lr_adj_rib_in_len(lr_adj_rib_in_t r);

/**
 * True when the Adj-RIB-In holds no routes. Returns 1 on a NULL handle.
 *
 * # Safety
 * See [`lr_adj_rib_in_len`].
 */
uint8_t lr_adj_rib_in_is_empty(lr_adj_rib_in_t r);

/**
 * Construct an empty Adj-RIB-Out (RFC 4271 §9).
 */
lr_adj_rib_out_t lr_adj_rib_out_new(void);

/**
 * Drop a boxed Adj-RIB-Out. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been produced by `lr_adj_rib_out_new` and not already
 * freed.
 */
void lr_adj_rib_out_free(lr_adj_rib_out_t r);

/**
 * Advertise one route to a destination. The `route` handle is *not*
 * consumed (the Adj-RIB-Out stores a clone). `tx_path_id` is the
 * RFC 7911 path identifier sent on the wire.
 *
 * # Safety
 * `r` must be a valid Adj-RIB-Out handle. `route` must be a valid
 * route handle.
 */
int32_t lr_adj_rib_out_advertise(lr_adj_rib_out_t r,
                                 uint64_t dest_peer,
                                 int32_t dest_proto,
                                 lr_route_t route,
                                 uint32_t tx_path_id);

/**
 * Suppress (withdraw) one (dest, key, path-id) tuple. Returns 1 when
 * a route was suppressed, 0 when no matching entry existed.
 *
 * # Safety
 * `r` must be a valid Adj-RIB-Out handle. `prefix` must be readable.
 */
int32_t lr_adj_rib_out_suppress(lr_adj_rib_out_t r,
                                uint64_t dest_peer,
                                int32_t dest_proto,
                                const struct lr_prefix_t *prefix,
                                uint16_t afi,
                                uint8_t safi,
                                const struct lr_prefix_t *source,
                                uint32_t tx_path_id);

/**
 * Total number of stored routes. Returns 0 on a NULL handle.
 *
 * # Safety
 * `r` must be a valid Adj-RIB-Out handle.
 */
uintptr_t lr_adj_rib_out_len(lr_adj_rib_out_t r);

/**
 * True when the Adj-RIB-Out holds no routes. Returns 1 on a NULL handle.
 *
 * # Safety
 * See [`lr_adj_rib_out_len`].
 */
uint8_t lr_adj_rib_out_is_empty(lr_adj_rib_out_t r);

/**
 * Construct an empty RibMux — cross-protocol mux (RFC 4271 §9 + the
 * admin-distance model the daemon uses to merge BGP / OSPF / Babel
 * routes into one FIB).
 */
lr_rib_mux_t lr_rib_mux_new(void);

/**
 * Drop a boxed RibMux. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been produced by `lr_rib_mux_new` and not already freed.
 */
void lr_rib_mux_free(lr_rib_mux_t r);

/**
 * Install one route into the mux. The `route` handle is *consumed*.
 *
 * # Safety
 * `r` must be a valid RibMux handle. `route` must be a valid route handle.
 */
int32_t lr_rib_mux_install(lr_rib_mux_t r, lr_route_t route);

/**
 * Uninstall a key. Returns 1 when a route was withdrawn, 0 when the
 * key was not present.
 *
 * # Safety
 * `r` must be a valid RibMux handle. `prefix` must be readable.
 */
int32_t lr_rib_mux_uninstall(lr_rib_mux_t r,
                             const struct lr_prefix_t *prefix,
                             uint16_t afi,
                             uint8_t safi,
                             const struct lr_prefix_t *source);

/**
 * Read the merged route for a key. Returns 0 on success and writes a
 * NEW `lr_route_t` handle (a *copy*) to `*out`. `LR_ERR_NULL` on a
 * NULL mux; 0 with `*out = NULL` when the key is absent.
 *
 * # Safety
 * `r` must be a valid RibMux handle. `prefix` and `out` must be readable.
 */
int32_t lr_rib_mux_get(lr_rib_mux_t r,
                       const struct lr_prefix_t *prefix,
                       uint16_t afi,
                       uint8_t safi,
                       const struct lr_prefix_t *source,
                       lr_route_t *out);

/**
 * Number of merged routes. Returns 0 on a NULL handle.
 *
 * # Safety
 * `r` must be a valid RibMux handle.
 */
uintptr_t lr_rib_mux_len(lr_rib_mux_t r);

/**
 * True when the mux holds no routes. Returns 1 on a NULL handle.
 *
 * # Safety
 * See [`lr_rib_mux_len`].
 */
uint8_t lr_rib_mux_is_empty(lr_rib_mux_t r);

/**
 * Apply the BIRD/FRR best-path selector to a flat array of route
 * handles. Returns the index of the winning route (>= 0), or -1 when
 * `count == 0` or every handle is NULL. The handles are *not*
 * consumed — the caller keeps ownership.
 *
 * # Safety
 * `routes` must point to `count` readable `lr_route_t` values.
 */
int64_t lr_route_selector_select(const lr_route_t *routes, uintptr_t count);

/**
 * Apply the BGP-specific best-path selector (RFC 4271 §9.1). Same
 * contract as [`lr_route_selector_select`].
 *
 * # Safety
 * See [`lr_route_selector_select`].
 */
int64_t lr_route_selector_select_bgp(const lr_route_t *routes, uintptr_t count);

/**
 * Install a ranked set of paths for a key (RFC 7911 — Add-Path
 * keeps more than one path per prefix; the first element is the
 * best path the non-Add-Path consumers see). The `routes` array
 * carries `count` route handles; ownership is **transferred** —
 * each handle is consumed and freed by this call (the LocRib
 * clones the underlying `Route` value).
 *
 * Returns 0 on success, `LR_ERR_NULL` (-1) on a NULL LocRib / NULL
 * routes / NULL key, `LR_ERR_OTHER` (-6) on a malformed key.
 *
 * # Safety
 * `r` must be a valid LocRib handle. `routes` (when `count > 0`)
 * must point to `count` valid `lr_route_t` handles. `key` must
 * point to a readable `lr_route_key_t`.
 */
int32_t lr_loc_rib_install_set(lr_loc_rib_t r,
                               const struct lr_route_key_t *key,
                               const lr_route_t *routes,
                               uintptr_t count);

/**
 * Number of paths stored for a key (RFC 7911 — Add-Path keeps more
 * than one). Returns 0 on a NULL handle or an unknown key.
 *
 * # Safety
 * `r` must be a valid LocRib handle. `key` must point to a
 * readable `lr_route_key_t`.
 */
uintptr_t lr_loc_rib_paths(lr_loc_rib_t r, const struct lr_route_key_t *key);

/**
 * Walk every best route in the Loc-RIB. The caller provides a
 * callback that receives one route handle per iteration (the
 * handle is borrowed — the caller must NOT free it). Returns the
 * number of routes visited, or `LR_ERR_NULL` (-1) on a NULL LocRib
 * / NULL callback.
 *
 * The callback signature is `void (*)(lr_route_t route, void
 * *user)`. The `user` pointer is passed through unchanged.
 *
 * # Safety
 * `r` must be a valid LocRib handle. `cb` must be a non-NULL
 * function pointer that does not free `route` and does not call
 * back into the FFI on the same LocRib handle (re-entrancy is
 * undefined — the LocRib borrow is held for the duration of the
 * walk).
 */
int64_t lr_loc_rib_iter_best(lr_loc_rib_t r, void (*cb)(lr_route_t route, void *user), void *user);

/**
 * Compute the diff between the Loc-RIB's current state and its
 * state at generation `since_gen` (RFC 8277 §3 / BMP §3 — the
 * generation-based delta the daemon uses to drive the BMP mirror,
 * the API socket thread and the redistribution pipe). Writes the
 * added / modified / removed counts to `*out_added` /
 * `*out_modified` / `*out_removed` and returns 0 on success,
 * `LR_ERR_NULL` on a NULL handle / NULL out-pointer.
 *
 * The diff is computed against the LocRib's history ring (16
 * entries deep); for older diffs the function returns 0 in all
 * three out-fields (no changes since the requested generation).
 *
 * # Safety
 * `r` must be a valid LocRib handle. All three out-pointers must
 * point to writable `uintptr_t`.
 */
int32_t lr_loc_rib_diff_since(lr_loc_rib_t r,
                              uint64_t since_gen,
                              uintptr_t *out_added,
                              uintptr_t *out_modified,
                              uintptr_t *out_removed);

/**
 * Create an empty ROA store. NULL on panic (last-error set).
 */
lr_roa_store_t lr_roa_store_new(void);

/**
 * Free a ROA store. NULL is a no-op. Must not run concurrently with
 * any other call on the same handle.
 *
 * # Safety
 * `s` must have been produced by [`lr_roa_store_new`] and must not
 * be freed twice.
 */
void lr_roa_store_free(lr_roa_store_t s);

/**
 * Atomically replace the **static** layer (local configuration) with
 * `len` entries. RTR-learned entries are preserved. Returns 0 on
 * success; -6 (`Other`) with the last-error string set when any
 * entry is malformed — in that case nothing is applied.
 *
 * # Safety
 * `s` must be a live store handle; `entries` must point at `len`
 * readable `lr_roa_entry_t`s (NULL with len 0 clears the layer).
 */
int32_t lr_roa_store_replace_static(lr_roa_store_t s,
                                    const struct lr_roa_entry_t *entries,
                                    uintptr_t len);

/**
 * Apply a batch of RTR deltas atomically (one completed sync).
 * Duplicates coalesce and unknown withdrawals are no-ops — the RFC
 * 8210 §5.6 / §12 code-6 semantics live in the set math. Returns 0
 * on success, -6 with last-error on a malformed entry (nothing
 * applied), -1/-4 as usual.
 *
 * # Safety
 * `s` must be a live store handle; `deltas` must point at `len`
 * readable `lr_roa_delta_t`s (NULL with len 0 is a no-op).
 */
int32_t lr_roa_store_apply_deltas(lr_roa_store_t s,
                                  const struct lr_roa_delta_t *deltas,
                                  uintptr_t len);

/**
 * Withdraw every RTR-learned entry — the RFC 8210 §6 data-expiry and
 * cache-change response. Static entries survive.
 *
 * # Safety
 * `s` must be a live store handle.
 */
int32_t lr_roa_store_clear_rtr(lr_roa_store_t s);

/**
 * Current merged entry count (static + RTR layers, deduplicated).
 * 0 on NULL / panic.
 *
 * # Safety
 * `s` must be NULL or a live store handle.
 */
uintptr_t lr_roa_store_len(lr_roa_store_t s);

/**
 * RFC 6811 §2 validation against the current snapshot. Writes
 * `LR_ROA_VALID` / `LR_ROA_NOT_FOUND` / `LR_ROA_INVALID` to
 * `out_state`. A NULL `origin_as` (no AS_PATH) validates as
 * `LR_ROA_NOT_FOUND` — a route without an origin AS is not covered
 * by any ROA.
 *
 * # Safety
 * `s` must be a live store handle; `addr_v4` (4 bytes) or `addr_v6`
 * (16 bytes) must be readable; `out_state` must be writable.
 */
int32_t lr_roa_store_validate(lr_roa_store_t s,
                              const uint8_t *addr_v4,
                              const uint8_t *addr_v6,
                              uint8_t prefix_len,
                              uint32_t origin_as,
                              uint8_t has_origin_as,
                              uint8_t *out_state);

/**
 * Construct an empty `RoaTableBuilder` (RFC 6482 — add entries via
 * `lr_roa_table_builder_add` / `_add_entry`, then call
 * `lr_roa_table_builder_build` to finalize).
 */
lr_roa_table_builder_t lr_roa_table_builder_new(void);

/**
 * Drop a boxed `RoaTableBuilder`. Safe to call with NULL.
 *
 * # Safety
 * `b` must have been produced by `lr_roa_table_builder_new` and not
 * already freed (or consumed by `_build`).
 */
void lr_roa_table_builder_free(lr_roa_table_builder_t b);

/**
 * Add one ROA by parsed-prefix string (RFC 6482 §3.1). The prefix
 * string follows the standard `"a.b.c.d/len"` (v4) or
 * `"xxxx:yyyy::/len"` (v6) form. `max_length` is `0` to use the
 * exact prefix length, otherwise must be `>= prefix_len` and `<=`
 * the address family width (32 v4 / 128 v6).
 *
 * Returns 0 on success, negative on error.
 *
 * # Safety
 * `b` must be a valid builder handle. `prefix` must point to a
 * NUL-terminated UTF-8 string.
 */
int32_t lr_roa_table_builder_add(lr_roa_table_builder_t b,
                                 const char *prefix,
                                 uint8_t max_length,
                                 uint32_t asn);

/**
 * Add one already-parsed ROA entry (the same `lr_roa_entry_t` shape
 * `lr_roa_store_replace_static` consumes). Returns 0 on success,
 * `LR_ERR_NULL` on a NULL builder, `LR_ERR_OTHER` (-6) when the
 * entry fails the RFC 6482 invariants.
 *
 * # Safety
 * `b` must be a valid builder handle. `entry` must point to a
 * readable `lr_roa_entry_t`.
 */
int32_t lr_roa_table_builder_add_entry(lr_roa_table_builder_t b, struct lr_roa_entry_t entry);

/**
 * Finalize the builder into an immutable `RoaTable`. Entries are
 * deduplicated and sorted; the trie index is built once. The
 * builder handle is consumed and freed.
 *
 * Returns a new `lr_roa_table_t` on success, NULL on a NULL
 * builder.
 *
 * # Safety
 * `b` must be a valid builder handle and is invalid after this call.
 */
lr_roa_table_t lr_roa_table_builder_build(lr_roa_table_builder_t b);

/**
 * Construct an empty `RoaTable` directly (no builder needed — use
 * `lr_roa_table_builder_add_entry` + `_build` to populate).
 */
lr_roa_table_t lr_roa_table_new(void);

/**
 * Drop a boxed `RoaTable`. Safe to call with NULL.
 *
 * # Safety
 * `t` must have been produced by a `lr_roa_table_*` constructor and
 * not already freed.
 */
void lr_roa_table_free(lr_roa_table_t t);

/**
 * Number of ROA entries in the table. Returns 0 on a NULL handle.
 *
 * # Safety
 * `t` must be a valid RoaTable handle.
 */
uintptr_t lr_roa_table_len(lr_roa_table_t t);

/**
 * True when the table holds no entries. Returns 1 (true) on a NULL
 * handle.
 *
 * # Safety
 * See [`lr_roa_table_len`].
 */
uint8_t lr_roa_table_is_empty(lr_roa_table_t t);

/**
 * Validate `(prefix, origin_as)` per RFC 6811 §2. `has_origin` is 0
 * to mean "no AS_PATH" (locally originated routes — returns
 * `NotFound`); otherwise `origin_as` carries the AS to validate
 * against.
 *
 * Returns one of the `LR_ROA_*` constants (`LR_ROA_VALID` = 0,
 * `LR_ROA_NOT_FOUND` = 1, `LR_ROA_INVALID` = 2 — matching the
 * values already exported by `roa_store.rs`).
 *
 * # Safety
 * `t` must be a valid RoaTable handle. `addr` must point to 4
 * (v4) or 16 (v6) readable bytes.
 */
uint8_t lr_roa_table_validate(lr_roa_table_t t,
                              const uint8_t *addr,
                              uint8_t is_ipv6,
                              uint8_t prefix_len,
                              uint32_t origin_as,
                              uint8_t has_origin);

/**
 * Read one ROA entry by index. Writes the entry's fields to the
 * out-pointers (`addr` carries v4 in the low 4 bytes when
 * `*out_is_ipv6 == 0`, all 16 bytes when `*out_is_ipv6 == 1`).
 * Returns 0 on success, `LR_ERR_NULL` on a NULL table,
 * `LR_ERR_INVALID_HANDLE` (-2) when the index is out of range.
 *
 * # Safety
 * `t` must be a valid RoaTable handle. The out-pointers must point
 * to writable memory of the right type.
 */
int32_t lr_roa_table_entry_at(lr_roa_table_t t,
                              uintptr_t index,
                              uint8_t *out_addr,
                              uint8_t *out_is_ipv6,
                              uint8_t *out_prefix_len,
                              uint8_t *out_max_length,
                              uint32_t *out_asn);

